CREATE TABLE "Employee" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,"employeeNumber" TEXT NOT NULL,"nameAr" TEXT NOT NULL,"nameEn" TEXT,"idNumber" TEXT,"nationality" TEXT,"dateOfBirth" DATETIME,"phone" TEXT,"email" TEXT,"address" TEXT,"department" TEXT,"jobTitle" TEXT,"hireDate" DATETIME,"managerId" INTEGER,"contractType" TEXT,"basicSalary" DECIMAL NOT NULL DEFAULT 0,"housingAllowance" DECIMAL NOT NULL DEFAULT 0,"transportAllowance" DECIMAL NOT NULL DEFAULT 0,"otherAllowance" DECIMAL NOT NULL DEFAULT 0,"bankName" TEXT,"iban" TEXT,"costCenter" TEXT,"status" TEXT NOT NULL DEFAULT 'ACTIVE',"idExpiry" DATETIME,"contractExpiry" DATETIME,"notes" TEXT,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL,CONSTRAINT "Employee_managerId_fkey" FOREIGN KEY ("managerId") REFERENCES "Employee"("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE TABLE "ExternalWorker" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,"workerNumber" TEXT NOT NULL,"name" TEXT NOT NULL,"affiliatedEntity" TEXT,"role" TEXT,"idNumber" TEXT,"phone" TEXT,"startDate" DATETIME,"endDate" DATETIME,"wage" DECIMAL NOT NULL DEFAULT 0,"paymentMethod" TEXT,"costCenter" TEXT,"status" TEXT NOT NULL DEFAULT 'ACTIVE',"notes" TEXT,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL);
CREATE TABLE "AttendanceRecord" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,"employeeId" INTEGER NOT NULL,"attendanceDate" DATETIME NOT NULL,"status" TEXT NOT NULL,"workHours" DECIMAL NOT NULL DEFAULT 0,"overtimeHours" DECIMAL NOT NULL DEFAULT 0,"fridayHours" DECIMAL NOT NULL DEFAULT 0,"checkIn" TEXT,"checkOut" TEXT,"notes" TEXT,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL,CONSTRAINT "AttendanceRecord_employeeId_fkey" FOREIGN KEY ("employeeId") REFERENCES "Employee"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "LeaveRequest" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,"employeeId" INTEGER NOT NULL,"leaveType" TEXT NOT NULL,"startDate" DATETIME NOT NULL,"endDate" DATETIME NOT NULL,"status" TEXT NOT NULL DEFAULT 'SUBMITTED',"reason" TEXT,"notes" TEXT,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL,CONSTRAINT "LeaveRequest_employeeId_fkey" FOREIGN KEY ("employeeId") REFERENCES "Employee"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "EmployeeAdvance" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,"advanceNumber" TEXT NOT NULL,"employeeId" INTEGER NOT NULL,"advanceDate" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"amount" DECIMAL NOT NULL,"recoveredAmount" DECIMAL NOT NULL DEFAULT 0,"remainingAmount" DECIMAL NOT NULL,"bankAccountId" INTEGER NOT NULL,"journalEntryId" INTEGER,"status" TEXT NOT NULL DEFAULT 'OPEN',"notes" TEXT,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL,CONSTRAINT "EmployeeAdvance_employeeId_fkey" FOREIGN KEY ("employeeId") REFERENCES "Employee"("id") ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT "EmployeeAdvance_bankAccountId_fkey" FOREIGN KEY ("bankAccountId") REFERENCES "BankAccount"("id") ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT "EmployeeAdvance_journalEntryId_fkey" FOREIGN KEY ("journalEntryId") REFERENCES "JournalEntry"("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE TABLE "PayrollRun" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,"payrollNumber" TEXT NOT NULL,"year" INTEGER NOT NULL,"month" INTEGER NOT NULL,"status" TEXT NOT NULL DEFAULT 'DRAFT',"totalGross" DECIMAL NOT NULL DEFAULT 0,"totalDeductions" DECIMAL NOT NULL DEFAULT 0,"totalNet" DECIMAL NOT NULL DEFAULT 0,"journalEntryId" INTEGER,"postedAt" DATETIME,"notes" TEXT,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL,CONSTRAINT "PayrollRun_journalEntryId_fkey" FOREIGN KEY ("journalEntryId") REFERENCES "JournalEntry"("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE TABLE "PayrollLine" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,"payrollRunId" INTEGER NOT NULL,"employeeId" INTEGER NOT NULL,"basicSalary" DECIMAL NOT NULL DEFAULT 0,"housingAllowance" DECIMAL NOT NULL DEFAULT 0,"transportAllowance" DECIMAL NOT NULL DEFAULT 0,"otherAllowances" DECIMAL NOT NULL DEFAULT 0,"normalWage" DECIMAL NOT NULL DEFAULT 0,"overtimeHours" DECIMAL NOT NULL DEFAULT 0,"overtimeValue" DECIMAL NOT NULL DEFAULT 0,"fridayHours" DECIMAL NOT NULL DEFAULT 0,"fridayValue" DECIMAL NOT NULL DEFAULT 0,"absenceDeduction" DECIMAL NOT NULL DEFAULT 0,"penalties" DECIMAL NOT NULL DEFAULT 0,"advances" DECIMAL NOT NULL DEFAULT 0,"otherDeductions" DECIMAL NOT NULL DEFAULT 0,"grossSalary" DECIMAL NOT NULL DEFAULT 0,"totalDeductions" DECIMAL NOT NULL DEFAULT 0,"netSalary" DECIMAL NOT NULL DEFAULT 0,"paymentStatus" TEXT NOT NULL DEFAULT 'DUE',"paidAmount" DECIMAL NOT NULL DEFAULT 0,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL,CONSTRAINT "PayrollLine_payrollRunId_fkey" FOREIGN KEY ("payrollRunId") REFERENCES "PayrollRun"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "PayrollLine_employeeId_fkey" FOREIGN KEY ("employeeId") REFERENCES "Employee"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "PayrollPayment" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,"payrollLineId" INTEGER NOT NULL,"paymentNumber" TEXT NOT NULL,"paymentDate" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"amount" DECIMAL NOT NULL,"bankAccountId" INTEGER NOT NULL,"journalEntryId" INTEGER,"notes" TEXT,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "PayrollPayment_payrollLineId_fkey" FOREIGN KEY ("payrollLineId") REFERENCES "PayrollLine"("id") ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT "PayrollPayment_bankAccountId_fkey" FOREIGN KEY ("bankAccountId") REFERENCES "BankAccount"("id") ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT "PayrollPayment_journalEntryId_fkey" FOREIGN KEY ("journalEntryId") REFERENCES "JournalEntry"("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE TABLE "ExternalWorkerCost" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,"costNumber" TEXT NOT NULL,"externalWorkerId" INTEGER NOT NULL,"costDate" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"periodLabel" TEXT,"amount" DECIMAL NOT NULL,"costCenter" TEXT NOT NULL,"expenseId" INTEGER,"status" TEXT NOT NULL DEFAULT 'POSTED',"notes" TEXT,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ExternalWorkerCost_externalWorkerId_fkey" FOREIGN KEY ("externalWorkerId") REFERENCES "ExternalWorker"("id") ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT "ExternalWorkerCost_expenseId_fkey" FOREIGN KEY ("expenseId") REFERENCES "Expense"("id") ON DELETE SET NULL ON UPDATE CASCADE);
PRAGMA defer_foreign_keys=ON;PRAGMA foreign_keys=OFF;
CREATE TABLE "new_Driver" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,"name" TEXT NOT NULL,"idNumber" TEXT,"phone" TEXT,"nationality" TEXT,"licenseNumber" TEXT,"licenseExpiry" DATETIME,"passportNumber" TEXT,"passportExpiry" DATETIME,"driverCardNumber" TEXT,"driverCardExpiry" DATETIME,"status" TEXT NOT NULL DEFAULT 'ACTIVE',"notes" TEXT,"employeeId" INTEGER,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL,CONSTRAINT "Driver_employeeId_fkey" FOREIGN KEY ("employeeId") REFERENCES "Employee"("id") ON DELETE SET NULL ON UPDATE CASCADE);
INSERT INTO "new_Driver" ("createdAt","driverCardExpiry","driverCardNumber","id","idNumber","licenseExpiry","licenseNumber","name","nationality","notes","passportExpiry","passportNumber","phone","status","updatedAt") SELECT "createdAt","driverCardExpiry","driverCardNumber","id","idNumber","licenseExpiry","licenseNumber","name","nationality","notes","passportExpiry","passportNumber","phone","status","updatedAt" FROM "Driver";DROP TABLE "Driver";ALTER TABLE "new_Driver" RENAME TO "Driver";CREATE UNIQUE INDEX "Driver_idNumber_key" ON "Driver"("idNumber");CREATE UNIQUE INDEX "Driver_employeeId_key" ON "Driver"("employeeId");PRAGMA foreign_keys=ON;PRAGMA defer_foreign_keys=OFF;
CREATE UNIQUE INDEX "Employee_employeeNumber_key" ON "Employee"("employeeNumber");CREATE UNIQUE INDEX "Employee_idNumber_key" ON "Employee"("idNumber");CREATE INDEX "Employee_department_idx" ON "Employee"("department");CREATE INDEX "Employee_status_idx" ON "Employee"("status");
CREATE UNIQUE INDEX "ExternalWorker_workerNumber_key" ON "ExternalWorker"("workerNumber");CREATE INDEX "AttendanceRecord_attendanceDate_idx" ON "AttendanceRecord"("attendanceDate");CREATE UNIQUE INDEX "AttendanceRecord_employeeId_attendanceDate_key" ON "AttendanceRecord"("employeeId","attendanceDate");CREATE INDEX "LeaveRequest_startDate_endDate_idx" ON "LeaveRequest"("startDate","endDate");
CREATE UNIQUE INDEX "EmployeeAdvance_advanceNumber_key" ON "EmployeeAdvance"("advanceNumber");CREATE UNIQUE INDEX "EmployeeAdvance_journalEntryId_key" ON "EmployeeAdvance"("journalEntryId");CREATE INDEX "EmployeeAdvance_employeeId_idx" ON "EmployeeAdvance"("employeeId");
CREATE UNIQUE INDEX "PayrollRun_payrollNumber_key" ON "PayrollRun"("payrollNumber");CREATE UNIQUE INDEX "PayrollRun_journalEntryId_key" ON "PayrollRun"("journalEntryId");CREATE UNIQUE INDEX "PayrollRun_year_month_key" ON "PayrollRun"("year","month");CREATE INDEX "PayrollLine_employeeId_idx" ON "PayrollLine"("employeeId");CREATE UNIQUE INDEX "PayrollLine_payrollRunId_employeeId_key" ON "PayrollLine"("payrollRunId","employeeId");
CREATE UNIQUE INDEX "PayrollPayment_payrollLineId_key" ON "PayrollPayment"("payrollLineId");CREATE UNIQUE INDEX "PayrollPayment_paymentNumber_key" ON "PayrollPayment"("paymentNumber");CREATE UNIQUE INDEX "PayrollPayment_journalEntryId_key" ON "PayrollPayment"("journalEntryId");CREATE UNIQUE INDEX "ExternalWorkerCost_costNumber_key" ON "ExternalWorkerCost"("costNumber");CREATE UNIQUE INDEX "ExternalWorkerCost_expenseId_key" ON "ExternalWorkerCost"("expenseId");CREATE INDEX "ExternalWorkerCost_costDate_idx" ON "ExternalWorkerCost"("costDate");
